insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('esp-t01','espanhol','Variantes linguísticas','treino','¿Cómo se llama el conjunto de formas distintas que hablantes de lugares, épocas, grupos o situaciones diferentes usan para decir la misma cosa?','["Falsos amigos", "Extranjerismos", "Onomatopeyas", "Variantes lingüísticas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t02','espanhol','Variantes linguísticas','treino','La variante lingüística que depende del LUGAR (país o región) donde vive el hablante se llama:','["Diafásica", "Diatópica", "Diastrática", "Diacrónica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t03','espanhol','Variantes linguísticas','treino','La variante lingüística que depende de la ÉPOCA, es decir, del paso del tiempo, se llama:','["Diacrónica", "Diastrática", "Diafásica", "Diatópica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t04','espanhol','Variantes linguísticas','treino','La variante lingüística que depende de la SITUACIÓN de comunicación (con quién hablo y si es formal o informal) se llama:','["Diafásica", "Diatópica", "Diastrática", "Diacrónica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t05','espanhol','Variantes linguísticas','treino','La variante lingüística relacionada con el grupo social, la edad, la profesión o el nivel de estudios del hablante se llama:','["Diatópica", "Diafásica", "Diastrática", "Diacrónica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t06','espanhol','Variantes linguísticas','treino','En México se dice "camión" para el autobús; en Cuba, "guagua"; en Argentina, "colectivo". ¿Qué tipo de variante es esta?','["Diacrónica", "Diafásica", "Diatópica", "Diastrática"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t07','espanhol','Variantes linguísticas','treino','Lucía le dice "¡Qué onda!" a su primo, pero "Buenos días, señora directora" en la escuela. ¿Qué tipo de variante usa?','["Diafásica", "Diatópica", "Diacrónica", "Diastrática"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t08','espanhol','Variantes linguísticas','treino','Hace siglos se decía "vuestra merced" para tratar a alguien con respeto; con el tiempo, esa expresión se transformó en "usted". ¿Qué tipo de variante es?','["Diastrática", "Diacrónica", "Diafásica", "Diatópica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t09','espanhol','Variantes linguísticas','treino','Los médicos dicen "cefalea" donde la mayoría de las personas dice "dolor de cabeza". ¿Qué tipo de variante es?','["Diacrónica", "Diastrática", "Diatópica", "Diafásica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t10','espanhol','Variantes linguísticas','treino','En España se dice "palomitas"; en Argentina, "pochoclo"; en Venezuela, "cotufas". ¿Qué alimento nombran todas esas palabras?','["Las papas fritas", "Las palomitas de maíz (pipoca)", "El pan dulce", "El helado de chocolate"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t11','espanhol','Variantes linguísticas','treino','¿Cuál de estas frases tiene una marca de INFORMALIDAD?','["Le ruego que me disculpe por el retraso.", "Nos vemos mañana en el cole, profe.", "Estimado señor director:", "Atentamente, Ana Gómez."]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t12','espanhol','Variantes linguísticas','treino','¿Cuál par muestra una abreviación informal y su forma completa (formal)?','["casa / hogar", "tele / televisión", "perro / can", "auto / carro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t13','espanhol','Variantes linguísticas','treino','En un texto formal, la frase "Mañana voy a viajar" (perífrasis de futuro) puede escribirse así:','["Mañana viaje.", "Mañana viajaré.", "Mañana viajaba.", "Mañana viajé."]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t14','espanhol','Variantes linguísticas','treino','¿En qué situación es más adecuado usar "usted"?','["Al hablar con el director del colegio, a quien acabas de conocer", "Al charlar con tu mejor amigo", "Al hablar con tu hermano menor", "Al jugar con un compañero de tu edad"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t15','espanhol','Variantes linguísticas','treino','"Tutear" a una persona significa:','["Tratarla de \"usted\", de forma formal", "Tratarla de \"tú\", de forma informal", "Interrumpirla mientras habla", "Hablar mal de ella a sus espaldas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t16','espanhol','Variantes linguísticas','treino','En un texto formal, la expresión metafórica "me quedé de piedra" puede cambiarse por:','["Me sorprendí muchísimo.", "Me quedé muy cansado.", "Me caí sobre una piedra.", "Me convertí en una estatua."]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t17','espanhol','Variantes linguísticas','treino','Reírse de una persona porque usa palabras típicas de su región es un ejemplo de:','["Prejuicio lingüístico", "Tratamiento formal", "Variante diacrónica", "Nivel culto"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t18','espanhol','Variantes linguísticas','treino','El nivel de lengua que busca precisión y rigor en el uso de las normas, como en un discurso oficial, es el nivel:','["Vulgar", "Culto", "Coloquial", "Jerga"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t19','espanhol','Variantes linguísticas','treino','El nivel de lengua que usamos en el día a día, con la familia y los amigos, es el nivel:','["Coloquial", "Jerga", "Técnico", "Culto"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t20','espanhol','Variantes linguísticas','treino','Los jugadores de videojuegos dicen "lag", "nerfear" y "respawn". Ese vocabulario propio de un grupo es un ejemplo de:','["Lenguaje formal", "Variante diacrónica", "Nivel culto", "Jerga"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t21','espanhol','Variantes linguísticas','treino','¿Qué afirmación sobre las variantes lingüísticas es correcta?','["Las palabras antiguas son siempre más correctas que las nuevas.", "Ninguna variante es un error: cada una sirve a su lugar, grupo o situación.", "Las variantes son errores de quien no estudió.", "Solo el español de España es correcto."]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t22','espanhol','Variantes linguísticas','treino','En Colombia y Venezuela se dice "chévere"; en España, "guay"; en México, "chido". ¿Qué significan esas palabras?','["Muy caro", "Aburrido", "Muy bueno, genial", "Rápido"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t23','espanhol','Comprensión lectora','treino','Lee: "Marina vive en Valparaíso, Chile. Los sábados sube al cerro donde vive su abuela y la ayuda a cuidar un pequeño huerto. Este año casi no llovió y muchas plantas se secaron. En vez de rendirse, las dos empezaron a guardar en baldes el agua de lavar las verduras para regar el huerto." ¿Por qué se secaron muchas plantas?','["Porque el huerto estaba en la playa", "Porque la abuela se olvidó de regarlas", "Porque casi no llovió", "Porque Marina se mudó de ciudad"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t24','espanhol','Comprensión lectora','treino','Lee: "Marina vive en Valparaíso, Chile. Los sábados sube al cerro donde vive su abuela y la ayuda a cuidar un pequeño huerto. Este año casi no llovió y muchas plantas se secaron. En vez de rendirse, las dos empezaron a guardar en baldes el agua de lavar las verduras para regar el huerto." ¿Qué hicieron Marina y su abuela para resolver el problema?','["Llevaron las plantas a la casa de Marina", "Abandonaron el huerto", "Guardaron el agua de lavar las verduras para regar el huerto", "Compraron plantas nuevas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t25','espanhol','Comprensión lectora','treino','Lee: "Marina vive en Valparaíso, Chile. Los sábados sube al cerro donde vive su abuela y la ayuda a cuidar un pequeño huerto. Este año casi no llovió y muchas plantas se secaron. En vez de rendirse, las dos empezaron a guardar en baldes el agua de lavar las verduras para regar el huerto." En el texto, "en vez de rendirse" quiere decir que Marina y su abuela:','["No se dieron por vencidas", "Se fueron de viaje", "Se cansaron y pararon", "Pidieron ayuda a los vecinos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t26','espanhol','Comprensión lectora','treino','Lee: "Estimada profesora Ruiz: Le escribo para informarle que mañana no podré asistir a clase, pues tengo una consulta con el dentista a las nueve. Le agradecería que me indicara qué tareas debo hacer. Atentamente, Tomás Pérez." ¿Por qué Tomás le escribe a la profesora?','["Para quejarse de las tareas", "Para pedir una nota más alta", "Para invitarla a una fiesta", "Para avisar que faltará a clase porque irá al dentista"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t27','espanhol','Comprensión lectora','treino','Lee: "Estimada profesora Ruiz: Le escribo para informarle que mañana no podré asistir a clase, pues tengo una consulta con el dentista a las nueve. Le agradecería que me indicara qué tareas debo hacer. Atentamente, Tomás Pérez." ¿Qué le pide Tomás a la profesora?','["Que le preste un libro", "Que cambie la fecha de la prueba", "Que llame a su madre", "Que le diga qué tareas debe hacer"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t28','espanhol','Comprensión lectora','treino','Lee: "Estimada profesora Ruiz: Le escribo para informarle que mañana no podré asistir a clase, pues tengo una consulta con el dentista a las nueve. Le agradecería que me indicara qué tareas debo hacer. Atentamente, Tomás Pérez." ¿Qué tipo de tratamiento usa Tomás?','["Informal: usa abreviaciones como \"profe\"", "Informal: tutea a la profesora", "Formal, porque usa jerga de estudiantes", "Formal: usa \"Estimada\", \"le\" (de usted) y \"Atentamente\""]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t29','espanhol','Comprensión lectora','treino','Lee el cartel: "BIBLIOTECA. Horario de verano: de lunes a viernes, de 8 h a 14 h. Sábados y domingos, cerrado. Los libros prestados deben devolverse en un plazo de quince días." Si vas un sábado por la tarde, la biblioteca:','["Estará cerrada", "Estará abierta todo el día", "Abrirá hasta las 14 h", "Abrirá a las 8 h"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t30','espanhol','Comprensión lectora','treino','Lee el cartel: "BIBLIOTECA. Horario de verano: de lunes a viernes, de 8 h a 14 h. Sábados y domingos, cerrado. Los libros prestados deben devolverse en un plazo de quince días." ¿Cuánto tiempo puedes quedarte con un libro prestado?','["Quince horas", "Cinco días", "Quince días (dos semanas)", "Un mes"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t31','espanhol','Comprensión lectora','treino','Lee el cartel: "BIBLIOTECA. Horario de verano: de lunes a viernes, de 8 h a 14 h. Sábados y domingos, cerrado. Los libros prestados deben devolverse en un plazo de quince días." Llegas un miércoles a las 15 h. ¿Qué pasa?','["La encuentras cerrada, porque de lunes a viernes cierra a las 14 h", "La encuentras abierta hasta las 16 h", "La encuentras abierta, porque es día de semana", "Solo puedes devolver libros, no pedirlos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t32','espanhol','Comprensión lectora','treino','Lee: "Diego, de 14 años, odiaba leer. Un día su tía le regaló una historieta de aventuras. La leyó en una sola tarde y pidió otra. Hoy, un año después, ya terminó tres novelas y quiere dibujar su propio cómic." ¿Qué cambió en la vida de Diego?','["Dejó de estudiar", "Se mudó a la casa de su tía", "Empezó a odiar los cómics", "Pasó a gustarle leer"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t33','espanhol','Comprensión lectora','treino','Lee: "Diego, de 14 años, odiaba leer. Un día su tía le regaló una historieta de aventuras. La leyó en una sola tarde y pidió otra. Hoy, un año después, ya terminó tres novelas y quiere dibujar su propio cómic." ¿Qué despertó el interés de Diego por la lectura?','["Un concurso de dibujo", "Una película de aventuras", "Una prueba difícil en la escuela", "Una historieta de aventuras que le regaló su tía"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t34','espanhol','Comprensión lectora','treino','Lee: "Diego, de 14 años, odiaba leer. Un día su tía le regaló una historieta de aventuras. La leyó en una sola tarde y pidió otra. Hoy, un año después, ya terminó tres novelas y quiere dibujar su propio cómic." ¿Qué quiere hacer Diego ahora?','["Dibujar su propio cómic", "Ser profesor de su tía", "Dejar de leer novelas", "Vender sus libros"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t35','espanhol','Comprensión lectora','treino','Lee el chat: "—¡Hola, Sofi! ¿Vamos al cine el viernes? —¡Dale! Pero antes tengo que terminar la tarea de mate. —Tranqui, te espero. ¿A las siete?" ¿Qué tiene que hacer Sofi antes de ir al cine?','["Ir a la escuela", "Comprar las entradas", "Llamar a su madre", "Terminar la tarea de matemáticas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t36','espanhol','Comprensión lectora','treino','Lee el chat: "—¡Hola, Sofi! ¿Vamos al cine el viernes? —¡Dale! Pero antes tengo que terminar la tarea de mate. —Tranqui, te espero. ¿A las siete?" En este chat, la palabra "mate" es:','["El nombre de la bebida argentina", "Un tipo de película", "Una abreviación informal de \"matemáticas\"", "El nombre de una amiga"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t37','espanhol','Comprensión lectora','treino','Lee el chat: "—¡Hola, Sofi! ¿Vamos al cine el viernes? —¡Dale! Pero antes tengo que terminar la tarea de mate. —Tranqui, te espero. ¿A las siete?" Cuando Sofi responde "¡Dale!", ella:','["Dice que está enojada", "Acepta la invitación", "Rechaza la invitación", "Pide que le den algo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t38','espanhol','Comprensión lectora','treino','El refrán "Más vale tarde que nunca" quiere decir que:','["Nunca hay que hacer nada por la tarde", "Es mejor llegar siempre tarde", "Es mejor hacer algo con retraso que no hacerlo", "Hay que dormir hasta tarde"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t39','espanhol','Aspectos culturales: Cuba','treino','¿Cuál es la capital de Cuba?','["San Juan", "Santiago de Chile", "Santo Domingo", "La Habana"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t40','espanhol','Aspectos culturales: Cuba','treino','¿Por qué se dice que Cuba parece un país "detenido en el tiempo"?','["Porque su calendario es diferente", "Porque nadie usa electricidad", "Por sus carros antiguos de los años 50 y su arquitectura clásica", "Porque allí no existen relojes"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t41','espanhol','Aspectos culturales: Cuba','treino','¿Quién fue Arnaldo Tamayo?','["Un cubano, el primer latinoamericano y hombre negro en viajar al espacio", "Un poeta que escribió sobre el son", "Un pintor que fundó el Ballet Nacional", "Un pirata que hundió un galeón"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t42','espanhol','Aspectos culturales: Cuba','treino','¿Quién fue Alicia Alonso?','["Una gran bailarina y coreógrafa, fundadora del Ballet Nacional de Cuba", "La presidenta del Fondo Monetario", "Una escritora de poemas sobre maracas", "La primera astronauta cubana"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t43','espanhol','Aspectos culturales: Cuba','treino','¿Qué se sabe sobre la alfabetización en Cuba?','["Solo la mitad de los adultos sabe leer", "Solo el 1% de los adultos sabe leer", "Cerca del 99% de los adultos saben leer y escribir", "No hay escuelas en el país"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t44','espanhol','Aspectos culturales: Cuba','treino','¿Cómo es la salud pública en Cuba?','["Es muy cara y solo para turistas", "No existen hospitales públicos", "Solo atiende a deportistas", "Es gratuita, y el país forma muchísimos médicos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t45','espanhol','Aspectos culturales: Cuba','treino','¿Qué monedas circulaban oficialmente en Cuba, que el gobierno intenta unificar?','["El dólar y el real", "El euro y la libra", "El peso cubano (CUP) y el peso convertible (CUC)", "El bolívar y el sol"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t46','espanhol','Aspectos culturales: Cuba','treino','En los deportes, Cuba:','["Es el primer país del mundo en medallas", "Solo participa en juegos de mesa", "Es el segundo país de América en medallas de oro, detrás de EE.UU.", "Nunca ganó una medalla olímpica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t47','espanhol','Aspectos culturales: Cuba','treino','¿Qué se cuenta sobre el galeón Santísima Trinidad?','["Fue el primer barco en llegar a la Luna", "Hoy es un museo flotante en Madrid", "Era un barco pirata inglés que atacó Brasil", "Se hundió por un huracán en 1711, cerca de La Habana, cargado de oro y plata"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t48','espanhol','Aspectos culturales: Cuba','treino','¿Quién fue Nicolás Guillén?','["Un astronauta cubano", "Un jugador de béisbol", "Un bailarín del Ballet Nacional", "Un poeta cubano, autor de \"Que siga el son\""]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t49','espanhol','Aspectos culturales: Cuba','treino','¿Qué instrumentos son típicos del son cubano?','["Berimbau, cuíca y pandeiro", "Gaita, banjo y sitar", "Arpa, órgano y piano de cola", "Bongó, maracas y güiro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-t50','espanhol','Aspectos culturales: Cuba','treino','Según el material estudiado, ¿qué juego existe en Cuba en lugar del "Monopolio"?','["Un juego de comprar playas y hoteles", "Un juego de cartas sobre carros antiguos", "\"Deuda eterna\", en que los jugadores son gobiernos del Tercer Mundo contra el FMI", "El ajedrez de los turistas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p01','espanhol','Variantes linguísticas','prova','Antiguamente se escribía "mesmo"; hoy se escribe "mismo". ¿Qué tipo de variante muestra este cambio?','["Diastrática", "Diafásica", "Diacrónica", "Diatópica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p02','espanhol','Variantes linguísticas','prova','Un abogado dice: "El demandado interpuso un recurso". Ese vocabulario propio de una profesión es un ejemplo de variante:','["Diacrónica", "Diastrática", "Diatópica", "Diafásica"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p03','espanhol','Variantes linguísticas','prova','En España se toma "zumo de naranja"; en gran parte de América, "jugo de naranja". ¿Qué tipo de variante es?','["Diatópica", "Diacrónica", "Diafásica", "Diastrática"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p04','espanhol','Variantes linguísticas','prova','¿Cuál de estas preguntas es FORMAL?','["Oye, ¿dónde queda la estación?", "¿Me pasás la dirección de la estación, porfa?", "Disculpe, señor, ¿podría indicarme dónde queda la estación?", "Che, ¿la estación está por acá?"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p05','espanhol','Variantes linguísticas','prova','En un texto formal, la frase "Ellos van a comer a las ocho" puede escribirse así:','["Ellos comieron a las ocho.", "Ellos coman a las ocho.", "Ellos comían a las ocho.", "Ellos comerán a las ocho."]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p06','espanhol','Comprensión lectora','prova','Lee el aviso: "CLUB DEL PARQUE. Se suspenden las clases de natación del jueves por limpieza de la piscina. Las clases se recuperarán el sábado a las 10 h. Traer gorro y toalla." ¿Por qué se suspenden las clases del jueves?','["Porque el profesor está enfermo", "Por la limpieza de la piscina", "Porque va a llover", "Porque es feriado"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p07','espanhol','Comprensión lectora','prova','Lee el aviso: "CLUB DEL PARQUE. Se suspenden las clases de natación del jueves por limpieza de la piscina. Las clases se recuperarán el sábado a las 10 h. Traer gorro y toalla." ¿Cuándo se recuperarán las clases?','["El viernes a las 8 h", "El sábado a las 10 h", "El jueves a las 10 h", "El domingo por la tarde"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p08','espanhol','Comprensión lectora','prova','Lee: "Querido diario: hoy perdí el autobús y llegué tarde a la prueba de Historia. El profesor me dejó entrar, pero tuve solo media hora. Aprendí la lección: esta noche pongo dos despertadores. Carla." ¿Qué le pasó a Carla?','["El profesor no la dejó entrar", "Perdió el autobús y llegó tarde a la prueba", "Olvidó estudiar para la prueba", "Se enfermó y faltó a la prueba"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p09','espanhol','Comprensión lectora','prova','Lee: "Querido diario: hoy perdí el autobús y llegué tarde a la prueba de Historia. El profesor me dejó entrar, pero tuve solo media hora. Aprendí la lección: esta noche pongo dos despertadores. Carla." ¿Qué decidió hacer Carla?','["Poner dos despertadores", "Pedir otra prueba", "Ir a pie todos los días", "Cambiar de escuela"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p10','espanhol','Aspectos culturales: Cuba','prova','¿Cuántos habitantes tiene Cuba, aproximadamente?','["Unos 500 mil", "Unos 11 millones", "Unos 200 millones", "Unos 50 millones"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p11','espanhol','Aspectos culturales: Cuba','prova','¿Qué hecho muestra la fuerza y la vitalidad de Alicia Alonso?','["Siguió bailando incluso después de quedarse ciega", "Viajó al espacio en 1980", "Ganó una medalla de oro en natación", "Encontró el tesoro del galeón"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('esp-p12','espanhol','Aspectos culturales: Cuba','prova','¿Qué grupo reúne cosas por las que Cuba es conocida en el mundo?','["Los tacos, los mariachis y las pirámides aztecas", "Los tangos, el mate y la Patagonia", "El flamenco, la paella y los toros", "El son cubano, los carros de los años 50 y los puros habanos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf');
insert into gabarito (questao_id,correta,explicacao) values
  ('esp-t01',3,'Quando a mesma coisa é dita de formas diferentes conforme o lugar, a época, o grupo ou a situação, temos variantes linguísticas.'),
  ('esp-t02',1,'Diatópica vem de "topos" = lugar. É a variação geográfica.'),
  ('esp-t03',0,'Diacrônica vem de "cronos" = tempo: palavras que somem e aparecem com o passar dos anos.'),
  ('esp-t04',0,'Diafásica é a variação conforme a situação: falamos diferente com um amigo e com um chefe.'),
  ('esp-t05',2,'Diastrática vem de "estrato" (camada social): muda conforme o grupo a que o falante pertence.'),
  ('esp-t06',2,'A palavra muda de país para país: é uma variação geográfica (diatópica).'),
  ('esp-t07',0,'A mesma pessoa, no mesmo lugar e época, muda o jeito de falar conforme a situação (informal × formal): variação diafásica.'),
  ('esp-t08',1,'A mudança aconteceu com o passar do tempo: variação diacrônica.'),
  ('esp-t09',1,'É o vocabulário de um grupo profissional (os médicos): variação diastrática.'),
  ('esp-t10',1,'São nomes regionais da pipoca: um bom exemplo de variante diatópica.'),
  ('esp-t11',1,'"Cole" (colegio) e "profe" (profesor) são abreviações, marca de linguagem informal. As outras são fórmulas formais.'),
  ('esp-t12',1,'"Tele" é a forma abreviada (informal) de "televisión". Os outros pares são sinônimos, não abreviações.'),
  ('esp-t13',1,'A perífrase "ir a + infinitivo" é mais informal; o futuro simples "viajaré" é a forma mais formal.'),
  ('esp-t14',0,'"Usted" é o tratamento formal, para pessoas mais velhas, desconhecidas ou com cargo (como um diretor).'),
  ('esp-t15',1,'Tutear = usar "tú" com alguém, sinal de proximidade (informalidade).'),
  ('esp-t16',0,'Expressões metafóricas são informais; no texto formal usamos a expressão precisa: "fiquei muito surpreso".'),
  ('esp-t17',0,'Achar que só existe um jeito "certo" de falar e zombar de quem fala diferente é preconceito linguístico.'),
  ('esp-t18',1,'Nível culto: cuidado com as regras, usado em situações oficiais e textos acadêmicos.'),
  ('esp-t19',0,'Nível coloquial: o uso cotidiano e espontâneo da língua.'),
  ('esp-t20',3,'Jerga (gíria) é o vocabulário de um grupo social ou profissão — aqui, os gamers.'),
  ('esp-t21',1,'Todas as variantes são legítimas. O importante é adequar a fala à situação e respeitar quem fala diferente.'),
  ('esp-t22',2,'As três querem dizer "muito legal". A palavra muda conforme o país: variante diatópica.'),
  ('esp-t23',2,'O texto diz: "Este año casi no llovió y muchas plantas se secaron" (quase não choveu).'),
  ('esp-t24',2,'Elas reaproveitaram a água de lavar verduras, guardada em baldes, para regar a horta.'),
  ('esp-t25',0,'"Rendirse" = desistir, render-se. "En vez de rendirse" = em vez de desistir.'),
  ('esp-t26',3,'Ele avisa que não poderá ir à aula ("no podré asistir") por causa da consulta no dentista.'),
  ('esp-t27',3,'"Le agradecería que me indicara qué tareas debo hacer" = agradeceria que me dissesse quais tarefas devo fazer.'),
  ('esp-t28',3,'Saudação "Estimada", o pronome "le" (tratamento de usted) e a despedida "Atentamente" são marcas de formalidade.'),
  ('esp-t29',0,'Sábados e domingos: "cerrado" (fechada).'),
  ('esp-t30',2,'"En un plazo de quince días" = no prazo de quinze dias.'),
  ('esp-t31',0,'De segunda a sexta ela abre das 8h às 14h. Às 15h já fechou.'),
  ('esp-t32',3,'No começo ele odiava ler; um ano depois já leu três romances.'),
  ('esp-t33',3,'Foi o presente da tia: uma "historieta" (história em quadrinhos).'),
  ('esp-t34',0,'O texto termina: "quiere dibujar su propio cómic".'),
  ('esp-t35',3,'"Tengo que terminar la tarea de mate": tem que terminar a lição de matemática.'),
  ('esp-t36',2,'No contexto da tarefa escolar, "mate" abrevia "matemáticas" — marca de linguagem informal.'),
  ('esp-t37',1,'"¡Dale!" é uma forma informal de dizer "combinado", "beleza".'),
  ('esp-t38',2,'Equivale ao nosso "antes tarde do que nunca".'),
  ('esp-t39',3,'A capital de Cuba é Havana (La Habana).'),
  ('esp-t40',2,'Os carros dos anos 1950 ainda circulando e os prédios clássicos dão essa impressão.'),
  ('esp-t41',0,'Arnaldo Tamayo (nascido em 1942) foi o primeiro astronauta latino-americano e negro.'),
  ('esp-t42',0,'Alicia Alonso (1921–2019) foi uma das maiores bailarinas clássicas do mundo e fundou o Balé Nacional de Cuba.'),
  ('esp-t43',2,'A taxa de alfabetização é de cerca de 99% entre os adultos (15 anos ou mais).'),
  ('esp-t44',3,'Consultas, remédios e cirurgias são gratuitos, e Cuba tem muitas faculdades de medicina.'),
  ('esp-t45',2,'Havia duas moedas, o CUP e o CUC, o que criava desigualdade e confundia turistas.'),
  ('esp-t46',2,'Nos Jogos Olímpicos e Pan-Americanos, Cuba só fica atrás dos Estados Unidos no continente.'),
  ('esp-t47',3,'O galeão espanhol afundou num furacão ao norte de Havana; o tesouro valeria hoje cerca de 400 milhões de dólares.'),
  ('esp-t48',3,'Nicolás Guillén é o grande poeta cubano; seus poemas se inspiram no son, a música popular cubana.'),
  ('esp-t49',3,'O son cubano usa bongô, maracas, güiro, violão, violino e acordeão.'),
  ('esp-t50',2,'O Banco Imobiliário (Monopólio) é proibido; no lugar existe o "Deuda eterna", contra o Fundo Monetário Internacional.'),
  ('esp-p01',2,'A palavra mudou com o passar do tempo: variação diacrônica.'),
  ('esp-p02',1,'Linguagem de um grupo profissional (jargão jurídico): variação diastrática.'),
  ('esp-p03',0,'A palavra muda conforme o lugar: variação diatópica.'),
  ('esp-p04',2,'"Disculpe", "señor" e "podría" (tratamento de usted, condicional de cortesia) são marcas de formalidade.'),
  ('esp-p05',3,'Troca-se a perífrase "ir a + infinitivo" pelo futuro simples "comerán".'),
  ('esp-p06',1,'"Por limpieza de la piscina" = por causa da limpeza da piscina.'),
